"""Export selection dimensions from the already pinned Ashe character record."""
import hashlib
import json
from pathlib import Path

raw = Path('docs/reference/ashe-progression.json').read_bytes()
assert hashlib.sha256(raw).hexdigest() == '8f92b1cfbb306f35f1a6555e41518fe141f1cceeee03bc4f0b7a9f4d0ccab512'
record = json.loads(raw)['sources'][0]['records']['Characters/Ashe/CharacterRecords/Root']
data = {'radius': record['selectionRadius'], 'height': record['selectionHeight']}
assert data == {'radius': 120.0, 'height': 155.0}
Path('src/content/ashe-selection.ts').write_text(
    '// Generated by tools/assets/export-ashe-selection.py from the pinned 16.18 CharacterRecord.\n'
    + 'export const ASHE_SELECTION = ' + json.dumps(data, indent=2) + ' as const;\n')
print('Exported Ashe selection radius 120 and height 155')
